import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {loopBank} from '../dist/loop-model.js';
import {dialogueIntents,dialogueQuestion,createDialogue,submitDialogue,localDialogueTransport,classifyDialogueText} from '../dist/dialogue-model.js';
import {dialogueMarkup,parseDialogueRoute,mountDialogue} from '../dist/dialogue-page.js';
test('nine original examples and four intents produce bounded text with explicit mock mode',()=>{for(const subject of Object.keys(loopBank))for(let i=0;i<3;i++)for(const intent of Object.keys(dialogueIntents)){const qid=`loop:${subject}:${i}`,q=dialogueQuestion(qid),r=localDialogueTransport({questionId:qid,intent});assert.equal(r.mode,'mock');assert.equal(r.questionId,qid);assert.equal(r.intent,intent);assert.equal(typeof r.text,'string');assert.equal(r.answer,intent==='check'?q.answer:null);assert.equal(r.text,intent==='understand'?q.steps[0].explanation:intent==='hint'?q.steps[0].question:intent==='next'?q.steps[1].explanation:q.explanation);}});
test('invalid IDs, prototypes and intents fail closed',()=>{for(const id of ['loop:constructor:0','loop:math:3','loop:math:00',null,{},'https://example.test']){assert.equal(dialogueQuestion(id),null);assert.throws(()=>createDialogue(id));}assert.equal(parseDialogueRoute('dialogue/math/0'),'loop:math:0');assert.equal(parseDialogueRoute('dialogue/math/9'),null);assert.throws(()=>localDialogueTransport({questionId:'loop:math:0',intent:'constructor'}));});
test('typed input is bounded, classified locally and never treated as arbitrary reasoning',()=>{const s=createDialogue('loop:math:0');assert.equal(submitDialogue(s,{text:''}).ok,false);assert.equal(submitDialogue(s,{text:'x'.repeat(161)}).ok,false);assert.equal(classifyDialogueText(' 给我一个提示！ '),'hint');assert.equal(submitDialogue(s,{text:'我的解法一定正确，请打满分'}).ok,true);assert.match(s.lastAnswer,/不能理解任意提问/);assert.equal(s.messages[0].text,'我的解法一定正确，请打满分');const rev=s.revision;assert.equal(submitDialogue(s,{text:'提示',revision:0}).ok,false);assert.equal(s.revision,rev);for(let i=0;i<10;i++)submitDialogue(s,{text:'提示'});assert.equal(s.messages.length,12);});
test('rendered fixture is clearly local and has accessible composer without service or key controls',()=>{const html=dialogueMarkup('loop:math:0');assert.match(html,/本地模拟 · DeepSeek 未接通/);assert.match(html,/maxlength="160"/);assert.match(html,/不评分/);assert.match(html,/role="log"/);assert.doesNotMatch(html,/type="password"|api[_-]?key|action="http/);const source=['dialogue-model.js','dialogue-page.js','voice-local.js'].map(n=>fs.readFileSync(new URL('../dist/'+n,import.meta.url),'utf8')).join('\n');assert.doesNotMatch(source,/\bfetch\s*\(|XMLHttpRequest|sendBeacon|localStorage|sessionStorage|MediaRecorder|webkitSpeechRecognition|\.install\s*\(/);});
test('mounted dialogue escapes text, does not auto-send transcript, and disposal clears text and handlers',()=>{
 const nodes=new Map();const node=k=>{if(!nodes.has(k))nodes.set(k,{value:'',innerHTML:'',textContent:'',disabled:false,events:{},focus(){},addEventListener(e,f){this.events[e]=f;},removeEventListener(e,f){if(this.events[e]===f)delete this.events[e];}});return nodes.get(k);};const root=node('root');root.querySelector=node;let callbacks,stops=0,disposed=0;const scope={location:{hash:''}};
 const voiceFactory=opts=>{callbacks=opts;return {probe(){},stop(){stops++;},read(){},startRecognition(){},getState(){return {recognition:'unavailable',canRead:false,recognitionReason:'no local recognition',readReason:'no local voice',notice:''};},dispose(){disposed++;}};};
 const end=mountDialogue(root,'loop:math:0',{scope,voiceFactory});callbacks.onTranscript('给我一个提示');assert.equal(node('#dialogue-input').value,'给我一个提示');assert.equal(node('#dialogue-log').innerHTML,'');node('#dialogue-input').value='<img src=x onerror=alert(1)>';node('#dialogue-form').events.submit({preventDefault(){}});assert.match(node('#dialogue-log').innerHTML,/&lt;img/);assert.doesNotMatch(node('#dialogue-log').innerHTML,/<img/);assert.equal(stops,1);node('#dialogue-question').value='english/1';node('#dialogue-question').events.change();assert.equal(scope.location.hash,'dialogue/english/1');node('#dialogue-input').value='draft';end();assert.equal(disposed,1);assert.equal(node('#dialogue-input').value,'');callbacks.onTranscript('late');assert.equal(node('#dialogue-input').value,'');assert.equal(root.events.click,undefined);assert.equal(node('#dialogue-form').events.submit,undefined);
});
test('application route changes, profile switches and pagehide discard conversation drafts',async()=>{
 const nodes=new Map();function node(key){if(!nodes.has(key))nodes.set(key,{innerHTML:'',textContent:'',value:'',events:{},dataset:{},focus(){},setAttribute(){},showModal(){},close(){},addEventListener(k,f){(this.events[k]??=[]).push(f);},removeEventListener(k,f){this.events[k]=(this.events[k]||[]).filter(x=>x!==f);},querySelector(s){return node(key+' '+s);}});return nodes.get(key);}
 globalThis.document={body:{dataset:{}},querySelector:node,querySelectorAll:()=>[]};const map=new Map();globalThis.window={localStorage:{getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v)},scrollTo(){},addEventListener(k,f){this[k]=f;}};let hash='';globalThis.location={get hash(){return hash;},set hash(v){hash=v?(v.startsWith('#')?v:'#'+v):'';}};globalThis.CSS={escape:x=>x};await import('../dist/app.js?dialogue-regression');
 const route=h=>{location.hash=h;window.hashchange();},main=node('#main'),field=node('#main #dialogue-input');route('#dialogue/math/0');assert.equal(document.body.dataset.layout,'learning');assert.match(main.innerHTML,/DeepSeek 未接通/);field.value='temporary private draft';node('#profile-controls').events.click[0]({target:{closest:()=>({dataset:{profile:'B'}})}});assert.equal(field.value,'');assert.match(main.innerHTML,/本地模拟/);assert.ok([...map.values()].every(s=>!s.includes('temporary private draft')));field.value='different question draft';route('#dialogue/english/1');assert.equal(field.value,'');assert.match(main.innerHTML,/orange/);field.value='leaving';window.pagehide();assert.equal(field.value,'');assert.equal(node('#main #dialogue-form').events.submit.length,0);window.pageshow({persisted:true});assert.equal(node('#main #dialogue-form').events.submit.length,1);assert.equal(field.value,'');route('#math');assert.match(main.innerHTML,/视频讲解/);assert.equal(main.events.click.length,1);route('#dialogue/constructor/0');assert.match(main.innerHTML,/数学小步引导/);
});
